window.CONSTRAINT_BRAIN={"start": ["Open a new project at a {tempo} tempo. Drag {asset} in and make it loop.","New project, {tempo} tempo. {asset} is your first brick: build two bars around it.","Start fresh at a {tempo} tempo. Make {asset} the first thing anyone hears."],"task": {"chords": ["Play a new melody over {asset} on your controller, recorded in one take.","Turn {asset} into a pad that swells in slowly.","Chop {asset} into short offbeat stabs.","Change one chord in {asset} to a surprise chord and keep it.","Play {asset} on three different instruments, one bar each."],"bass": ["Make {asset} the star: find it a sound that growls.","Play {asset} back on your controller, but change the rhythm by feel.","Put {asset} an octave up and turn it into a lead.","Answer {asset} with a second line that only plays in its gaps."],"drums": ["Load {asset} on a kit you have never used and make it groove.","Replace one drum in {asset} with a sound you record through your interface.","Play a fill on top of {asset} with your pads or keys, one take.","Take {asset} to half time and make it feel heavy."],"arp": ["Put {asset} on a sound that sparkles and ride the filter live with a knob.","Slow {asset} to half speed and let it breathe.","Use {asset} as the rhythm of a drum part instead of notes.","Delete half the notes of {asset} and make the rest count."],"motif": ["Build a whole hook out of {asset}: repeat it, then change one note.","Harmonise {asset} with a second voice a third above.","Play {asset} backwards on your controller.","Turn {asset} into a bassline."],"beat": ["Build a groove on top of {asset} with one instrument you play in live.","Chop {asset} and rearrange the hits into a new pattern.","Resample {asset} through one weird effect and use only the result.","Play a bassline that locks with the kick of {asset}."],"texture": ["Use {asset} as the bed for a whole section.","Slice {asset} into notes and play a melody with them.","Automate a filter on {asset} with a knob on your controller, recorded live.","Reverse {asset} and make it lead into your drop."],"hit": ["Make {asset} the snare, the kick or the clap. Your choice, commit.","Play {asset} as a melody across your keyboard.","Hide {asset} somewhere it surprises the listener.","Build a whole rhythm from {asset} alone."],"riser": ["Use {asset} to lift into a new section, then cut everything for one beat.","Reverse {asset} and make it a fall instead of a rise.","Chop {asset} into a stutter fill.","Play {asset} against a drop you build from scratch."],"chop": ["Warp {asset} to your tempo and build on it.","Cut {asset} into slices on your pads and play them in a new order.","Pitch {asset} until it fits your track and make it sing.","Use just one hit from {asset} and make it the hook."]},"rules": {"hands": ["Every new note is played in on your controller, no drawing.","Record one knob or fader move live and keep it.","Use only the pads, or only the keys: one of the two.","One take only. Mistakes are features."],"ears": ["Record one sound through your interface: voice, desk, keys, anything.","Make one sound tiny and one sound enormous.","Something must move all the time: automate.","Leave two beats of silence somewhere and earn them."],"tools": ["Use exactly one effect, but automate it.","Stock devices only.","Pick a preset you would never choose and keep it.","No EQ this round."],"time": ["Keep it to eight bars.","Finish something small you could play right now.","Spend the first minute just listening, hands off.","Bounce what you made before the timer ends."],"space": ["Pan one element hard left and one hard right.","Put one sound in a huge room and keep everything else dry.","Mono until the last minute, then go wide once.","One sound far away, one right in the listener’s ear."],"voice": ["Add your own voice, even a whisper or a breath.","Make a sound with your mouth and turn it into an instrument.","Hum the next part into your interface, then play it on a synth.","Say one word and chop it into a rhythm."]},"evolve": ["Keep everything from last round. Add {asset} on top.","Mute half of what you made last round. {asset} fills the gap.","Resample your last round into one audio file and use it with {asset}.","Take last round’s best moment and build a new section around it with {asset}.","Make the opposite mood of last round, still using what you have, plus {asset}.","Last round becomes the verse. {asset} starts the chorus."],"finale": ["Last round: give it an ending and bounce 30 seconds. {asset} is your final ingredient.","Finish line: arrange what you have into intro, peak and ending. Use {asset} once, where it matters."],"feels": [["slow",72,88],["laid-back",88,100],["mid",100,116],["upbeat",118,128],["fast",128,145],["very fast",160,176]], "shifts": [["Keep your tempo",1],["Keep your tempo",1],["Slow it down a little",0.9],["Speed it up a little",1.1],["Make it much slower",0.75],["Push it much faster",1.25],["Go half time",1],["Go double time",1]]};

